const cfg = $('Config').first().json;
const zone = $now.zoneName;
const today = $now.startOf('day');
const dayKey = (n) => today.minus({ days: n }).toFormat('yyyy-MM-dd');
const r2 = (x) => Math.round(x * 100) / 100;

const parseDate = (v) => {
  if (v === undefined || v === null || v === '') return null;
  const s = String(v).trim();
  let m = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (m) return m[1] + '-' + m[2] + '-' + m[3];
  m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/); // US style M/D/YYYY
  if (m) return m[3] + '-' + m[1].padStart(2, '0') + '-' + m[2].padStart(2, '0');
  return null;
};
const parseAmount = (v) => {
  const n = Number(String(v === undefined || v === null ? '' : v).replace(/[^0-9.\-]/g, ''));
  return Number.isFinite(n) ? n : 0;
};
const makeBook = () => ({
  days: {},
  add(key, amount, product) {
    const d = this.days[key] || (this.days[key] = { total: 0, orders: 0, products: {} });
    d.total += amount;
    d.orders += 1;
    if (product) d.products[product] = (d.products[product] || 0) + amount;
  },
  sum(keys) {
    const out = { total: 0, orders: 0, products: {} };
    for (const k of keys) {
      const d = this.days[k];
      if (!d) continue;
      out.total += d.total;
      out.orders += d.orders;
      for (const [p, v] of Object.entries(d.products)) out.products[p] = (out.products[p] || 0) + v;
    }
    return out;
  },
});

const sheet = makeBook();
const stripe = makeBook();
let rowsRead = 0;
let stripeSeen = false;
let stripeCharges = 0;
for (const item of $input.all()) {
  const j = item.json;
  if (j && j.object === 'list' && Array.isArray(j.data)) {
    stripeSeen = true;
    for (const ch of j.data) {
      if (ch.status !== 'succeeded' || ch.paid === false) continue;
      if (String(ch.currency).toUpperCase() !== String(cfg.currency).toUpperCase()) continue;
      const key = new Date(ch.created * 1000).toLocaleDateString('en-CA', { timeZone: zone });
      stripe.add(key, (ch.amount - (ch.amount_refunded || 0)) / 100, ch.description || '');
      stripeCharges += 1;
    }
  } else if (j && j[cfg.dateColumn] !== undefined) {
    const key = parseDate(j[cfg.dateColumn]);
    if (!key) continue;
    sheet.add(key, parseAmount(j[cfg.amountColumn]), String(j[cfg.productColumn] || '').trim());
    rowsRead += 1;
  }
}

const range = (from, to) => { const a = []; for (let n = from; n <= to; n++) a.push(dayKey(n)); return a; };
const pack = (b, keys) => { const s = b.sum(keys); return { total: r2(s.total), orders: s.orders, products: s.products }; };
const pct = (cur, prev) => (prev > 0 ? Math.round(((cur - prev) / prev) * 1000) / 10 : null);

const t = pack(sheet, [dayKey(0)]);
const y = pack(sheet, [dayKey(1)]);
const d2 = pack(sheet, [dayKey(2)]);
const l7 = pack(sheet, range(1, 7));
const p7 = pack(sheet, range(8, 14));
const topProducts = Object.entries(l7.products).sort((a, b) => b[1] - a[1]).slice(0, 3)
  .map(([name, total]) => ({ name, total: r2(total) }));
const strip = (o) => ({ total: o.total, orders: o.orders });

return [{ json: {
  businessName: cfg.businessName,
  currency: cfg.currency,
  reportDate: dayKey(0),
  yesterdayDate: dayKey(1),
  today: strip(t),
  yesterday: strip(y),
  dayBefore: strip(d2),
  last7: strip(l7),
  prev7: strip(p7),
  yesterdayVsDayBeforePct: pct(y.total, d2.total),
  last7VsPrev7Pct: pct(l7.total, p7.total),
  averageOrderValueLast7: l7.orders ? r2(l7.total / l7.orders) : null,
  topProducts,
  stripe: stripeSeen ? {
    charges: stripeCharges,
    today: strip(pack(stripe, [dayKey(0)])),
    yesterday: strip(pack(stripe, [dayKey(1)])),
    last7: strip(pack(stripe, range(1, 7))),
  } : null,
  rowsRead,
} }];

const aiText = (j) => {
  try { return String(j.choices[0].message.content || ''); } catch (e) { return ''; }
};
const aiJson = (j) => {
  try {
    const v = JSON.parse(aiText(j));
    return v && typeof v === 'object' && !Array.isArray(v) ? v : null;
  } catch (e) { return null; }
};
const k = $('Aggregate KPIs').first().json;
const fmt = (n) => new Intl.NumberFormat('en-US', { style: 'currency', currency: k.currency || 'USD' }).format(n || 0);
const pctText = (p) => (p === null || p === undefined ? 'n/a' : (p >= 0 ? '+' : '') + p + '%');
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const ord = (n) => n + (n === 1 ? ' order' : ' orders');

const ai = aiJson($json);
let lines = ai && Array.isArray(ai.lines) ? ai.lines.map((s) => String(s).trim()).filter(Boolean).slice(0, 5) : [];
const aiOk = lines.length >= 3;
if (!aiOk) {
  lines = [
    'Yesterday (' + k.yesterdayDate + '): ' + fmt(k.yesterday.total) + ' from ' + ord(k.yesterday.orders) + ' (' + pctText(k.yesterdayVsDayBeforePct) + ' vs day before).',
    'Last 7 days: ' + fmt(k.last7.total) + ' from ' + ord(k.last7.orders) + ' (' + pctText(k.last7VsPrev7Pct) + ' vs previous 7 days).',
    'Top products: ' + (k.topProducts.length ? k.topProducts.map((p) => p.name + ' ' + fmt(p.total)).join(', ') : 'no product data') + '.',
    'Today so far: ' + fmt(k.today.total) + ' from ' + ord(k.today.orders) + '.',
    '(AI summary unavailable - figures above are computed directly from your sales log.)',
  ];
}
const table = [
  ['Today so far', fmt(k.today.total), k.today.orders],
  ['Yesterday', fmt(k.yesterday.total), k.yesterday.orders],
  ['Last 7 days', fmt(k.last7.total), k.last7.orders],
  ['Previous 7 days', fmt(k.prev7.total), k.prev7.orders],
];
const slackText = '*Daily KPI report - ' + k.businessName + ' (' + k.reportDate + ')*\n' + lines.join('\n') +
  '\n\n' + table.map((r) => '*' + r[0] + ':* ' + r[1] + ' (' + ord(r[2]) + ')').join('  |  ');
const html = '<div style="font-family:Arial,sans-serif;font-size:14px;color:#222">' +
  '<h2 style="margin:0 0 8px">Daily KPI report - ' + esc(k.businessName) + '</h2>' +
  '<p style="color:#666;margin:0 0 12px">' + esc(k.reportDate) + '</p>' +
  lines.map((l) => '<p style="margin:4px 0">' + esc(l) + '</p>').join('') +
  '<table style="border-collapse:collapse;margin-top:14px">' +
  table.map((r) => '<tr><td style="padding:4px 14px 4px 0;color:#666">' + esc(r[0]) + '</td><td style="padding:4px 14px 4px 0"><b>' + esc(r[1]) + '</b></td><td style="color:#666">' + ord(r[2]) + '</td></tr>').join('') +
  '</table></div>';
return { json: { slackText, subject: 'Daily KPI report - ' + k.businessName + ' - ' + k.reportDate, html, aiStatus: aiOk ? 'ok' : 'fallback' } };
